SELECT CASE WHEN YEAR(order_date) < 2024 THEN 'before_2024' WHEN YEAR(order_date) = 2024 THEN '2024' ELSE 'after_2024' END AS order_cohort, customer_id, COUNT(*) AS num_orders, MIN(amount) AS min_amount FROM orders WHERE customer_id IS NULL GROUP BY CASE WHEN YEAR(order_date) < 2024 THEN 'before_2024' WHEN YEAR(order_date) = 2024 THEN '2024' ELSE 'after_2024' END, customer_id ORDER BY min_amount DESC, order_cohort, customer_id LIMIT 5;
